import hashlib,json,sys,tarfile,zipfile
from pathlib import Path
p,site=map(Path,sys.argv[1:3]);results=[]
for archive_name,extracts in [('sdk-source.tar.gz',['source','source-repro']),('pyjwt-source.tar.gz',['pyjwt-source'])]:
 with tarfile.open(p/archive_name,'r:gz') as a:
  for extraction in extracts:
   compared=0;mismatches=[]
   for member in a.getmembers():
    if member.isfile():
     compared+=1;target=p/extraction/member.name
     if not target.is_file() or target.read_bytes()!=a.extractfile(member).read():mismatches.append(member.name)
   results.append({'archive':archive_name,'archive_sha256':hashlib.sha256((p/archive_name).read_bytes()).hexdigest(),'extraction':extraction,'original_regular_files_compared':compared,'mismatches':mismatches})
wheel=p/'pyjwt-2.15.0-py3-none-any.whl';compared=0;mismatches=[]
with zipfile.ZipFile(wheel) as z:
 for n in z.namelist():
  if n.endswith('.py'):
   compared+=1
   if (site/n).read_bytes()!=z.read(n):mismatches.append(n)
results.append({'artifact':wheel.name,'sha256':hashlib.sha256(wheel.read_bytes()).hexdigest(),'installed_python_sources_compared':compared,'mismatches':mismatches})
source=p/'pyjwt-source/pyjwt-1d41a6478e1562e68ff667fcd703356acf085f68';sdist=p/'pyjwt-sdist/pyjwt-2.15.0';matches=[]
for name in ['tests/test_api_jwt.py','tests/test_jwks_client.py','tests/utils.py','tox.ini','pyproject.toml']:
 a=(source/name).read_bytes();b=(sdist/name).read_bytes()
 assert a==b,name
 matches.append({'path':name,'sha256':hashlib.sha256(a).hexdigest(),'tag_sdist_byte_identical':True})
print(json.dumps({'archive_and_installed_checks':results,'tag_sdist_selected_test_inputs':matches},indent=2))
